sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.hod-department-page {
  max-width: 1180px;
  margin: 30px auto;
  padding: 0 20px;
  font-family: Arial, sans-serif;
  color: #0f1b45;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
}

.page-header p {
  margin: 0;
  color: #7c859a;
}

.back-link {
  color: #1769e0;
  text-decoration: none;
}

.summary-card {
  display: inline-flex;
  align-items: center;
  gap: 15px;
  background: #ffffff;
  border: 1px solid #e5e9f0;
  border-radius: 12px;
  padding: 15px 20px;
  margin-bottom: 22px;
}

.summary-label {
  font-weight: 600;
}

.summary-value {
  min-width: 34px;
  height: 34px;
  border-radius: 17px;
  background: #e8f8f2;
  color: #16875d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.department-card {
  background: #ffffff;
  border: 1px solid #e4e8ef;
  border-radius: 14px;
  padding: 22px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.department-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid #edf0f4;
}

.department-title h3 {
  margin: 0;
  font-size: 20px;
}

.department-title span {
  color: #7c859a;
  font-size: 13px;
}

.member-table {
  width: 100%;
  border-collapse: collapse;
}

.member-table th {
  text-align: left;
  padding: 14px 12px;
  background: #f7f9fc;
  font-size: 13px;
}

.member-table td {
  padding: 14px 12px;
  border-bottom: 1px solid #edf0f4;
  font-size: 14px;
}

.employee-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.employee-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #eee9ff;
  color: #5e35b1;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: 700;
}

.active-pill {
  display: inline-block;
  background: #e6f7ef;
  color: #16875d;
  padding: 5px 10px;
  border-radius: 14px;
  font-size: 12px;
  font-weight: 600;
}

.empty-row {
  text-align: center;
  color: #8b93a5;
  padding: 28px !important;
}

@media (max-width: 800px) {
  .page-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }

  .table-responsive {
    overflow-x: auto;
  }
}

sp_widget.script:
(function() {

    data.departmentName = "";
    data.departmentCode = "";
    data.members = [];

    var departmentId = "";

    // Get logged-in HOD
    var userGR = new GlideRecord('sys_user');

    if (userGR.get(gs.getUserID())) {

        departmentId =
            userGR.getValue('department') || "";

        data.departmentName =
            userGR.getDisplayValue('department') || "";
    }

    if (!departmentId)
        return;


    // Get department code from cmn_department
    var deptGR = new GlideRecord('cmn_department');

    if (deptGR.get(departmentId)) {

        data.departmentCode =
            deptGR.getValue('id') || "";
    }


    // Get active users in same department
    var memberGR = new GlideRecord('sys_user');

    memberGR.addQuery(
        'department',
        departmentId
    );

    memberGR.addQuery(
        'active',
        true
    );

    memberGR.orderBy('name');
    memberGR.query();

    while (memberGR.next()) {

        var memberName =
            memberGR.getDisplayValue('name') || "";

        var initials = "";

        var nameParts =
            memberName.split(" ");

        for (
            var i = 0;
            i < nameParts.length && i < 2;
            i++
        ) {
            if (nameParts[i]) {
                initials +=
                    nameParts[i]
                    .charAt(0)
                    .toUpperCase();
            }
        }

        data.members.push({

            sys_id:
                memberGR.getUniqueValue(),

            name:
                memberName,

            initials:
                initials,

            email:
                memberGR.getValue('email') || "-",

            department:
                memberGR.getDisplayValue('department') || "-"

        });
    }

})();
